/**
 * Sidebar + top bar composition for the tenant subtree.
 *
 * Owner D. A Server Component: it does the permission and flag work once, on
 * the server, and hands the results to `AppSidebar` and `TopBar` as props. The
 * domain components stay presentational — none of them may reach for `can()` or
 * a service on their own.
 *
 * Must call (do not reimplement): can, isEnabled
 */

import Link from "next/link";
import type { ReactNode } from "react";
import { AppSidebar } from "@/components/domain/nav/app-sidebar";
import { TopBar } from "@/components/domain/nav/top-bar";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export type DashboardShellProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  unreadCount: number;
  /** Current path, so the sidebar can mark the active entry. */
  pathname: string;
  panel?: ReactNode;
  children?: ReactNode;
};

export function DashboardShell(props: DashboardShellProps) {
  const { org, actor, flags, projects, unreadCount, pathname, panel, children } =
    props;

  const flagContext = buildFlagContext(actor, org);

  const mayCreateProject = can(actor, "project:create", {
    kind: "project",
    orgId: org.id,
    projectId: "" as Project["id"],
    visibility: "org",
    leadId: actor.userId,
  });

  const searchEnabled = isEnabled("command_palette", flagContext);

  return (
    <div className="flex min-h-screen">
      <AppSidebar
        org={org}
        actor={actor}
        flags={flags}
        projects={projects}
        pathname={pathname}
      />

      <div className="flex min-w-0 flex-1 flex-col">
        <TopBar org={org} actor={actor} unreadCount={unreadCount} flags={flags} />

        <div className="flex items-center gap-4 border-b border-slate-200 bg-white px-6 py-2 text-sm">
          {searchEnabled ? (
            <Link href={`/${org.slug}/search`} className="text-slate-600">
              Search
            </Link>
          ) : null}
          {mayCreateProject ? (
            <Link
              href={`/${org.slug}/projects/new`}
              className="ml-auto rounded-md bg-indigo-600 px-3 py-1.5 font-medium text-white"
            >
              New project
            </Link>
          ) : null}
        </div>

        <div className="flex min-h-0 flex-1">
          <main className="min-w-0 flex-1 px-6 py-8">{children}</main>
          {panel !== undefined ? (
            <aside className="hidden w-80 shrink-0 border-l border-slate-200 bg-white xl:block">
              {panel}
            </aside>
          ) : null}
        </div>
      </div>
    </div>
  );
}
"use client";

/**
 * Client context provider seeded with the org, actor, flag snapshot and the
 * quota checks the layout already computed.
 *
 * Owner D. This file is a thin adapter over the single context definition in
 * `@/hooks/org-context` — it exists only so the layout can spread the four
 * values as props instead of building the context object itself. There is
 * deliberately no second `createContext()` here: `useOrg`, `usePermission`
 * and `usePlanLimits` read the context this renders, and two providers would
 * mean the hooks silently saw `null`.
 */

import type { ReactElement, ReactNode } from "react";
import {
  OrgProvider as OrgContextProvider,
  type OrgContextValue,
} from "@/hooks/org-context";

export { OrgContext, type OrgContextValue } from "@/hooks/org-context";

export type OrgProviderProps = Omit<OrgContextValue, "limitChecks"> &
  Partial<Pick<OrgContextValue, "limitChecks">> & {
    children?: ReactNode;
  };

export function OrgProvider(props: OrgProviderProps): ReactElement {
  const { org, actor, flags, limitChecks = [], children } = props;

  return (
    <OrgContextProvider value={{ org, actor, flags, limitChecks }}>
      {children}
    </OrgContextProvider>
  );
}
"use client";

/**
 * Role-aware sidebar: every item is filtered through `can()` and its flag.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import Link from "next/link";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav, type NavItem } from "@/config/nav";
import { cn } from "@/lib/cn";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { orgPath, projectPath } from "@/lib/url";
import { orgFlagContext } from "@/hooks/flag-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { OrgSwitcher } from "./org-switcher";

export type AppSidebarProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  pathname: string;
  /** Orgs offered by the switcher; defaults to just the current one. */
  organizations?: readonly Organization[];
};

/** True when `pathname` is the item's route or lives beneath it. */
export function isActiveSegment(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function AppSidebar(props: AppSidebarProps): ReactElement | null {
  const { org, actor, flags, projects, pathname, organizations } = props;

  // The nav tree declares the permission and flag each item needs; `visibleNav`
  // applies both. Nothing here branches on `actor.role`.
  const context = orgFlagContext(org, actor);
  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
  const settings = visibleNav(SETTINGS_NAV, actor, flags);

  // The project shortcut list is its own gate: reading projects at all, and
  // the public-projects flag for the "shared" affordance.
  const mayReadProjects = can(
    actor,
    "project:read",
    organizationResource(org.id),
  );
  const publicProjectsOn =
    flags.public_projects === true || isEnabled("public_projects", context);

  function renderItem(item: NavItem): ReactElement {
    const href = orgPath(org.slug, item.segment);
    return (
